            return true;
        } catch (Fail failure) {
            undoTo(mark);
            add(pkt, LVL[level], pkt.pn, epoch, failure.code, null);
            close(pkt, failure.offset, failure.code);
            return false;
        } finally {
            closeStatus = null;
            closeOffset = 0;
        }
