        if (code == 0x1c || code == 0x1d) {
            connectionClose(cur, out, code == 0x1c);
            return;
        }
        if (code == 0x30) {
            out.writeBytes(cur.rest());
            return;
        }
        if (code == 0x31) {
            cur.varint();
            byte[] data = cur.take(last(cur));
            writeVar(out, data.length);
            out.writeBytes(data);
            return;
        }
        throw new Fail(ENCODING, 0);
    }

    private static long last(Cur cur) {
        return cur.parsed;
    }
