def credit(st, s, cand, cfg):
    if cand > cfg['lim']['stream']: e('FLOW_CONTROL_ERROR')
    if st['used'] - s['high'] + cand > cfg['lim']['connection']: e('FLOW_CONTROL_ERROR')

def set_high(st, s, cand):
    st['used'] += cand - s['high']
    s['high'] = cand

def ref_stream(st, sid, receive, cfg):
    mod = sid & 3; idx = sid >> 2
    if receive:
        if mod == 0:
            if idx >= cfg['lim']['bidi']: e('STREAM_LIMIT_ERROR')
            st['opened'][0] = max(st['opened'][0], idx + 1)
        elif mod == 2:
            if idx >= cfg['lim']['uni']: e('STREAM_LIMIT_ERROR')
            st['opened'][1] = max(st['opened'][1], idx + 1)
        elif mod == 1:
            if idx >= cfg['loc']['bidi']: e('STREAM_STATE_ERROR')
        else:
            e('STREAM_STATE_ERROR')
    else:
        if mod == 0:
            if idx >= cfg['lim']['bidi']: e('STREAM_LIMIT_ERROR')
            st['opened'][0] = max(st['opened'][0], idx + 1)
        elif mod == 1:
            if idx >= cfg['loc']['bidi']: e('STREAM_STATE_ERROR')
        elif mod == 3:
            if idx >= cfg['loc']['uni']: e('STREAM_STATE_ERROR')
        else:
            e('STREAM_STATE_ERROR')
    s = st['streams'].get(sid)
    if s is None:
        s = {'high': 0, 'final': None, 'reset': None, 'stop': None, 'send_max': 0, 'bytes': {}}
        st['streams'][sid] = s
    s['listed'] = True
    return s

def output(st, cfg, rows, drows, closed_row):
    streams = []
    for sid in sorted(st['streams']):
        s = st['streams'][sid]
        if not s.get('listed'): continue
        r = bytes_ranges(s['bytes'])
        pre = prefix_of(r)
        prefix_bytes = bytes([s['bytes'][k] for k in range(pre)])
        streams.append({'id': sid, 'high': s['high'], 'final': s['final'], 'reset': s['reset'],
                        'stop': s['stop'], 'send_max': s['send_max'],
                        'ranges': [[a, b] for a, b in r], 'unique': len(s['bytes']), 'prefix': pre,
                        'sha256': hashlib.sha256(prefix_bytes).hexdigest()})
    crypto = []
