private void stopSending(Cur cur, ByteArrayOutputStream out) {
    long id = cur.varint();
    long error = cur.varint();
    out.writeBytes(vi(id));
    out.writeBytes(vi(error));
    Stream stream = reference(id, false);
    if (stream.stop == null) setStop(stream, error);
}

private void commitMaxData(long maximum) {
    if (maximum > sendMaxData) {
        final long previous = sendMaxData;
        sendMaxData = maximum;
        journal.add(() -> sendMaxData = previous);
    }
}

private void commitMaxStreams(long maximum, boolean bidirectional) {
    if (bidirectional) {
        if (maximum > sendMaxStreamsBidi) {
            final long previous = sendMaxStreamsBidi;
            sendMaxStreamsBidi = maximum;
            journal.add(() -> sendMaxStreamsBidi = previous);
        }
    } else if (maximum > sendMaxStreamsUni) {
        final long previous = sendMaxStreamsUni;
        sendMaxStreamsUni = maximum;
        journal.add(() -> sendMaxStreamsUni = previous);
    }
}

private void commitSendMax(Stream stream, long maximum) {
    if (maximum > stream.sendMax) {
        final long previous = stream.sendMax;
        stream.sendMax = maximum;
        journal.add(() -> stream.sendMax = previous);
    }
}

